_SA = [("Ang lakas-lakas ng hagupit ng daluyong ng bagyo dito sa Samar.", "The whipping of the storm surge here in Samar is extremely strong."), ("Ang laking gulat ko kasi hindi pala basta-bastang bagyo lang ito.", "I was so shocked because it turns out this is not just an ordinary typhoon."), ("Nagdulot ito ng malawakang pagbaha.", "It caused extensive flooding."), ("Ang lawak-lawak ng pinsala dito sa bayan namin dahil halos tinangay nito lahat ng ari-arian, mga gusali at pananim.", "The damage here in our town is very extensive because it almost carried away all the properties, buildings and crops."), ("Marami ang nalunod.", "Many drowned."), ("Gumuho din ang lupa sa lugar ng biyenan ko.", "The ground also caved in at my in-laws’ place."), ("Naputol ang mga kuryente, walang komunikasyon, at naparalisa ang transportasyon.", "The electricity was cut, there was no communication and transportation was paralyzed."), ("Sa Davao naman nung nakaraang linggo, marami-rami rin ang naapektuhan nang nanalasa ang buhawi.", "In Davao last week, quite a number were also affected when the tornado struck."), ("Nasira ang mga palayan at mga plantasyon.", "The ricefields and plantations were destroyed."), ("Ilang bata ang naitalang nasawi at nawawala pa.", "A few children were reported killed and some are still missing."), ("May mga malubha ding nasugatan.", "There are also some who were seriously injured."), ("E, kamakailan lang may tagtuyot.", "Well, there was a drought just recently."), ("Perwisyo ito sa magsasaka, ngayon naman buhawi.", "It was an inconvenience to the farmers, and now a tornado."), ("Kamakalawa lang e isang bangkang puno ng mangingisda ang natangay ng ipu-ipo.", "The day before yesterday a boat full of fishermen was carried away by a cyclone.")]
