        + [M("What does siyanga pala mean?", "by the way", ["of course", "good luck", "never mind"], "siyanga pala."), M("What does ubod mean in ubod nang lakas?", "very", ["a little", "not", "almost"], "ubod."), M("What does saksakan nang tigas ng ulo mean?", "very hardheaded", ["very strong", "very quiet", "very fast"], "saksakan."), M("What is the cognate of sakuna?", "aksidente", ["siyensiya", "perwisyo", "kuryente"], "sakuna."), M("What does hudyat mean?", "signal", ["warning", "damage", "road"], "hudyat."), M("What does nagkabuhol-buhol mean for traffic?", "became a tangled mess", ["moved smoothly", "was light", "was stopped by police"], "buhol."), M("What is the sign of summer coming according to Poging Bisdak?", "the weakening northeast monsoon", ["a typhoon", "snow", "a strong wind"], "hudyat ng tag-init."), M("What do Red Cross volunteers do?", "respond quickly even in far-flung areas", ["warn people by radio", "fix roads", "forecast the weather"], "rumesponde.")]
