_IA = [("Ang lakas-lakas ng hagupit ng daluyong bagyo dito sa Samar.", "The storm surge here in Samar is extremely strong."), ("Ang lawak-lawak ng pinsala dito sa bayan.", "The damage is very extensive here in the town."), ("Wasak na wasak ang bukid.", "The field was (very) damaged extensively."), ("Tiyak, napakarami na namang sakuna sa daan.", "Surely there will be a lot of accidents again on the streets."), ("Ubod nang lakas pa rin ang hangin.", "The wind is still very strong."), ("Saksakan ng tigas ng ulo din kasi.", "Because (someone) is also very hardheaded.")]
_IT = [("lakas", "ang lakas-lakas", "malakas na malakas", "ubod ng lakas", "pagkalakas-lakas"), ("lawak", "ang lawak-lawak", "malawak na malawak", "ubod ng lawak", "pagkalawak-lawak"), ("init", "ang init-init", "mainit na mainit", "ubod ng init", "pagkainit-init"), ("hangin", "ang hangin-hangin", "mahanging-mahangin", "ubod ng hangin", "pagkahangin-hangin")]
_MA = [("Medyo humihina na raw ang hanging amihan.", "They say the monsoon winds are getting a bit weaker."), ("Marami-rami rin ang naapektuhan nang manalasa ang buhawi.", "When the tornado hit, quite a number of people were affected."), ("Malawak rin naman ang plantasyon.", "The plantation is a little wide."), ("Medyo mahina na nga.", "It is indeed a little weak already."), ("Medyo lubog nang kaunti sa tubig.", "A little submerged in water."), ("Medyo lubog sa tubig.", "A little flooded.")]
_MT = [("mahina-hina", "medyo mahina", "mahina nang kaunti", "mahina rin naman"), ("marami-rami", "medyo marami", "marami nang kaunti", "marami rin naman"), ("wala", "medyo lubog", "lubog nang kaunti", "lubog rin naman"), ("mahangin-hangin", "medyo mahangin", "mahangin nang kaunti", "mahangin rin naman")]
_PL = [("mga malakas na bagyo", "malakas na mga bagyo", "malalakas na bagyo", "malalakas na mga bagyo"), ("mga malalawak na bukid", "malalawak na mga bukid", "malalawak na bukid", "malalawak na mga bukid"), ("mga malamig na hangin", "malamig na mga hangin", "malalamig na hangin", "malalamig na mga hangin")]
L3 = lesson(
    "C9 L3 · Intensified and moderative adjectives; pluralizing adjectives",
    "Ang lakas-lakas · Ubod nang lakas · Medyo mahina · Malalakas na bagyo",
    requires=[],
    cards=[
        card("A. Intensified adjectives", "Read these sentences from the presentations. The first three show one way of intensifying adjectives, using the duplicated word; the fourth shows a second way, using the prefix napaka. A third way is to add phrases like ubod nang, sobrang and saksakan ng to the root word.", examples=passage(_IA)),
        card("More ways to intensify", "Other phrases to signify intensified adjectives are hari ng … and grabeng …, both translated “extremely.” A fourth way is to affix pagka to the duplicated root word: pagkalakas-lakas, pagkaganda-ganda, pagkatigas-tigas. There is no difference in meaning; this is a higher-level way of expressing intensified adjectives in Tagalog."),
        card("Table of intensified forms", "", tables=[table(["Root", "ang + duplicated root", "duplicate adjective", "ubod/saksakan ng + root", "pagka + duplicated root"], [list(r) for r in _IT], say=[0, 1, 2, 3, 4])]),
        card("B. Moderative adjectives (taken up in Chapter 4)", "Moderative adjectives translate as “a little ...”:", examples=passage(_MA)),
        card("Forms of moderative adjectives", "Adding rin naman gives the moderative form: maganda rin naman means “a little pretty,” malamig rin naman “a little cold.” The moderative with rin naman comes with the entire adjective, not just the root word. Adding medyo to the entire adjective also creates a moderative: medyo mahina is “a little weak” (mahina is a ma adjective); medyo lubog sa tubig is “a little flooded” (lubog is a non-ma adjective). A third way is nang kaunti after the adjective: medyo lubog sa tubig becomes lubog nang kaunti sa tubig. Native speakers may put both medyo and nang kaunti in the same phrase: Medyo lubog nang kaunti sa tubig ang Maynila. Warning: nang kaunti cannot be placed immediately before a noun (Hindi ba marumi nang kaunting tubig-baha iyan? is wrong; use Hindi ba medyo maruming tubig-baha iyan? or marumi-ruming). Native speakers also tend to put kahit papano (paano) at the end of the moderative adjective; it loosely translates as “considering” and softens the effect of something negative."),
        card("Table of moderative forms", "", tables=[table(["duplicate root", "medyo + adjective", "adjective + nang kaunti", "adjective + rin naman"], [list(r) for r in _MT], say=[0, 1, 2, 3])]),
        card("C. Pluralizing adjectives", "In Tagalog the adjective does not have to be in the plural form even if the noun is plural. There are five ways to signal plurality in an adjective + noun structure, subsumed under two general ways: the marker mga, and pluralizing the adjective itself. 1. Use mga before the singular adjective (mga malakas na bagyo), or with the noun and keep the adjective singular (malakas na mga bagyo). 2. Pluralize the adjective itself (malalakas na bagyo); then the noun does not need mga, and in translation the noun becomes plural. Caveat: native speakers are heard saying mga malalakas na mga bagyo, which embodies all the versions above."),
        card("Table of pluralization forms", "", tables=[table(["Form 1a", "Form 1b", "Form 2a", "Form 2b"], [list(r) for r in _PL], say=[0, 1, 2, 3])]),
    ],
    exercises=uniq(
        tr_q(_IA) + rev_q(_IA) + tr_q(_MA) + rev_q(_MA)
        + [M(f"What is the {kind} of the adjective root {r}?", form, dd([x[i] for x in _IT], form), form) for r, a1, a2, a3, a4 in _IT for kind, i, form in [("duplicated ang form", 1, a1), ("duplicated adjective form", 2, a2), ("ubod ng form", 3, a3), ("pagka form", 4, a4)]]
        + [M(f"What is the {kind} of {r}?", form, dd([x[i] for x in _MT], form), form) for r, a1, a2, a3 in _MT[:1] + _MT[1:2] + _MT[3:] for kind, i, form in [("medyo form", 1, a1), ("nang kaunti form", 2, a2), ("rin naman form", 3, a3)]]
        + [M(f"Which is the plural form 2a of {x[0].split(' ', 2)[2]}?", x[2], dd([y[2] for y in _PL], x[2]), x[2]) for x in _PL]
        + [M("Which phrase means “extremely”?", "grabeng or hari ng", ["medyo", "rin naman", "nang kaunti"], "extremely."), M("Which prefix intensifies a duplicated root at a higher level?", "pagka", ["napaka", "ma", "mag"], "pagka."), M("What does maganda rin naman mean?", "a little pretty", ["very pretty", "not pretty", "the prettiest"], "rin naman."), M("What does kahit papano do at the end of a moderative adjective?", "softens a negative", ["makes it stronger", "makes it plural", "makes it a question"], "kahit papano."), M("Can nang kaunti be placed right before a noun?", "No", ["Yes, always", "Only with plurals", "Only with names"], "warning."), M("In how many general ways can plurality be signaled?", "two: mga and pluralizing the adjective", ["one", "three", "four"], "two general ways."), M("What is the plural of malakas na bagyo using plural form 2a?", "malalakas na bagyo", ["mga malakas na bagyo", "malakas na mga bagyo", "malakasan na bagyo"], "2a.")]
        + [F("___ ng lakas ang hangin. (very)", "Ubod", ["Medyo", "Mga"], "ubod."), F("Medyo ___ ang hangin. (weak)", "mahina", ["malakas", "mahangin"], "medyo + adjective."), F("Ang ___-lawak ng pinsala. (so wide)", "lawak", ["malawak", "lawakan"], "reduplicated root."), F("___ na bagyo ang tumama. (strong, plural)", "Malalakas", ["Malakas", "Malakasan"], "plural.")]
    ),
)

