_SP1 = [("MSGT Macalinta", "Magandang hapon po, Kumander. Kailangan po namin ng volunteers, pagkain at gamot. Napakalakas ng tsunami kaya lubhang napinsala ang buong bayan.", "Good afternoon, Commander. We need volunteers, food and medicine. The tsunami was so strong that the whole town was severely damaged."), ("Kumander", "Ilan ang nasugatan at namatay? Mga ilang bahay ang nawasak ng tsunami?", "How many were injured and killed? About how many houses were destroyed by the tsunami?"), ("MSGT Macalinta", "May tatlumpung bahagyang nasugatan, limang malubhang nasugatan at limang namatay. Mga limampung bahay ang lubos na nawasak. May naiulat ding pinsalang dalawandaang milyong piso sa mga plantasyon.", "There are about thirty slightly injured, five seriously injured and five dead. About fifty houses were totally destroyed. Damage of two hundred million pesos to the plantations was also reported."), ("Kumander", "Magpapadala ako ng mas maraming sundalo at sibilyang volunteers sa lugar.", "I will send more troops and civilian volunteers to the area.")]
_SP2 = [("Miranda", "Magandang hapon, Jojie. Narinig kong may darating na daluyong ng bagyo.", "Good afternoon, Jojie. I heard there will be a storm surge."), ("Jojie", "Magandang hapon din, Miranda. Narinig din namin sa balita sa TV.", "Good afternoon too, Miranda. We also heard it on the TV news."), ("Miranda", "Umalis na kayo agad at humanap ng matutuluyan sa mataas na lugar. Kung wala kayong matutuluyan, may kapatid akong lalaki sa kalapit na isla na puwedeng tumanggap sa inyo ng pamilya mo. Ligtas ang lugar at tiyak na hindi binabaha.", "Leave immediately and find shelter on high ground. If you have no place to stay, I have a brother on a nearby island who can take you and your family in. The place is safe and certainly not flooded."), ("Jojie", "Nag-iimpake na kami ng asawa ko at ng mga bata ng mahahalagang gamit. Salamat sa pag-aalala, Miranda. Wala pa kaming matutuluyan. Puwede ko bang malaman ang pangalan, address at numero ng kapatid mo?", "My wife, the kids and I are packing important belongings. Thank you for your concern, Miranda. We don’t have a place to stay yet. May I know your brother’s name, address and number?"), ("Miranda", "Oo, ibibigay ko ang kumpletong detalye. Mag-ingat kayo.", "Yes, I will give the complete details. Take care."), ("Jojie", "Maraming salamat sa tulong.", "Thank you very much for the help.")]
