_RS = [("Ayon sa abiso ng DepEd, walang klase sa elementarya at hayskul dahil sa itinaas na ng PAGASA ang senyal bilang dalawa sa Metro Manila.", "According to the DepEd advisory, there are no classes in elementary and high school because PAGASA has raised signal number two in Metro Manila."), ("Ilang babala na ang narinig natin na masama ang El Niño ngayong taon.", "We have heard several warnings that this year’s El Niño is bad."), ("Samantala, nakaranas ng buhawi ang ilang bahagi ng Kamaynilaan. Pero ano nga ba ang buhawi?", "Meanwhile, some parts of Greater Manila experienced a tornado. But what really is a tornado?"), ("Ang pag-apaw o pagragasa ng tubig-dagat sa lupa dulot ng bagyo ang tinatawag na daluyong ng bagyo.", "The overflow or rushing of seawater onto land caused by a typhoon is called a storm surge."), ("Libu-libong tao ang apektado ng panganib mula sa matinding lagay ng panahon tulad ng ipu-ipo at bagyo.", "Thousands of people are affected by the danger from severe weather such as cyclones and typhoons."), ("Nararanasan pa rin ang malawakang pagbaha, sa kabila ng maaraw na panahon sa Bataan.", "Extensive flooding is still being experienced, despite the sunny weather in Bataan."), ("Dahil sa climate change, ang wet season natin ay magiging mas malubha at ang tag-init ay magiging mas mainit.", "Because of climate change our wet season will become more severe and the summer hotter."), ("Labis na naaapektuhan ang mga pananim at livestocks sa pagtama ng tagtuyot.", "Crops and livestock are greatly affected when a drought hits."), ("Lampas na yata sa Signal Number Tres ang bagyong ito dahil ubod nang lakas ng hangin, e.", "This typhoon has probably gone past Signal Number Three because the wind is very strong.")]
