L7 = lesson(
    "C9 L3 · Speaking practice, glossary and sample sentences",
    "Kailangan po namin ng volunteers · Umalis na kayo agad · Glossary",
    requires=[],
    cards=[
        card("Activity 11: guided conversation", "You are MSGT Macalinta of the Philippine Army, part of the rescue team during a typhoon that hit Bacolod City. At 1600 hours, call your unit commander: say you need volunteers, food and medicines and that the tsunami was so severe that the entire town was badly damaged. B asks about the number of injured, the casualties and the approximate number of houses destroyed; A says about 30 slightly injured, 5 seriously injured, 5 deaths, about 50 houses totally destroyed and about 200 million pesos damage to plantations; B says he will send more troops and civilian volunteers. Use buhawi, naapektuhan, nasalanta, malubhang nasugatan, namatay, nasawi, pinsala, napinsala, kabuuang pinsala, bahagyang nasira, nawasak, lubos na nawasak and others. A sample:", examples=dlg(_SP1)),
        card("Activity 12: role play, a storm surge warning", "You are Miranda; your friend Jojie lives in Leyte. At 5 p.m. greet him, say you heard there will be a storm surge, advise him to leave immediately and take shelter on high ground; if he has no place, offer your brother on a nearby island where he and his family can stay temporarily, a safe, unflooded place; give the brother’s full name, complete address and phone number. Jojie (B): returns the greeting, says you all heard it on TV news, that you, your wife and kids are packing important belongings, thanks Miranda and says you don’t have a place yet, asks for the brother’s name, address and number, and thanks Miranda. A sample (the brother’s details are left out):", examples=dlg(_SP2)),
        card("Activity 13: challenge yourself, a situation report", "The book prints an authentic English situation report of the National Disaster Risk Reduction and Management Council on the effects of typhoon Pablo (as of December 13, 2012, 10 a.m.). Two partners translate it into Tagalog, using Tagalog and Spanish derivatives for numbers, and report it in the order of the headings. Student 1 covers the affected population (barangays, municipalities, families and persons), casualties (dead and injured), lifelines (impassable bridges and roads, areas with power interruption), damaged properties (houses totally damaged), the cost of damage (total, and infrastructure) and the cost of assistance (total, the social welfare department and local governments). Student 2 covers the evacuation centers (families and persons served), casualties (missing and rescued), lifelines (water supply and communication interruptions), houses partially damaged, the cost of damage to agriculture and private property, and the cost of assistance from the health department, the council and other agencies. A summary of its figures (numbers of 1000 and above are written out in the book; here are the figures):", tables=[table(["Heading", "Figures (summary)"], [list(r) for r in _SIT], say=[])]),
        card("Glossary", "", tables=[ttable(_GL)]),
        card("Words and phrases used to report severe weather: sample sentences", "The book’s sample sentences (the book misprints cliimate and senyal; they are corrected here):", examples=passage(_RS)),
        card("Words and phrases used to report the effects of severe weather: sample sentences", "", examples=passage(_ES)),
        card("Activities left out", "The pair work, the situation cards and the page for additional vocabulary."),
    ],
    exercises=uniq(
        tr_q([(t, e) for _, t, e in _SP1]) + rev_q([(t, e) for _, t, e in _SP1]) + tr_q([(t, e) for _, t, e in _SP2]) + rev_q([(t, e) for _, t, e in _SP2]) + tr_q(_GL) + rev_q(_GL[:15]) + rev_q(_GL[15:30]) + rev_q(_GL[30:]) + tr_q(_RS) + rev_q(_RS) + tr_q(_ES) + rev_q(_ES)
        + [M("How do you say “Leave immediately and find shelter on high ground”?", "Umalis na kayo agad at humanap ng matutuluyan sa mataas na lugar.", ["Manatili kayo agad sa mababang lugar.", "Bumili kayo agad ng bangka.", "Umalis na kayo bukas."], "umalis."), M("What is a storm surge, according to the sample sentence?", "the overflow or rushing of seawater onto land caused by a typhoon", ["a very strong wind", "a heavy rain", "a long drought"], "daluyong ng bagyo."), M("What does the sample sentence say about the weather in Casiguran?", "two tourists drowned because of bad weather", ["it was sunny", "there was a drought", "classes were canceled"], "nalunod."), M("In the situation report, how many persons were dead?", "902", ["2,661", "934", "136"], "sitrep."), M("In the situation report, how many persons were rescued?", "136", ["902", "2,661", "934"], "sitrep."), M("What were the houses damaged in total?", "148,887", ["88,090", "60,797", "63"], "sitrep.")]
        + [F("Sa oras ng ___, siguraduhin na nasa loob ng bahay ang mga bata. (calamity)", "kalamidad", ["trapiko", "babala"], "kalamidad."), F("Naapektuhan ang libu-libong pamilya ng sunud-sunod na ___. (typhoons)", "pagbagyo", ["pagtaya", "pagbaha"], "pagbagyo."), F("Mistulang ___ ang buong probinsiya ng Leyte. (paralyzed)", "naparalisa", ["nasira", "nawala"], "naparalisa.")]
    ),
)

